const trig=$('Execute Workflow Trigger').first().json;
const name=String(trig.name||'workflow');
const id=trig.id;
const sanitized=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'workflow';
return[{json:{repo_owner:trig.repo_owner,repo_name:trig.repo_name,repo_path:trig.repo_path,repo_branch:trig.repo_branch||'main',fileName:`${sanitized}__${id}.json`,workflowName:name,workflowId:id}}];

const files=$input.all();
const ids=new Set($('Filter').all().map(i=>i.json.id));
const seen=new Set();
const orphans=[];
for(const item of files){
  const f=item.json;
  if(f.type&&f.type!=='file')continue;
  const name=f.name||'';
  const m=name.match(/__([A-Za-z0-9]+)\.json$/);
  if(!m)continue;
  const id=m[1];
  if(ids.has(id))continue;
  const filePath=f.path;
  if(!filePath||seen.has(filePath))continue;
  seen.add(filePath);
  orphans.push({json:{origin:'github',name,filePath,id,hasOrphans:true}});
}
if(orphans.length===0)return[{json:{hasOrphans:false}}];
return orphans;

const gv=$('Lookup global variables').first().json;
const raw=String(gv.gh_repo_path??'').replace(/^\/+/, '');
const repo_path=!raw||raw.endsWith('/')?raw:`${raw}/`;
return $input.all().map(i=>({json:{...i.json,repo_owner:gv.gh_repo_owner,repo_name:gv.gh_repo_name,repo_path,repo_branch:'main'}}));

const s=$getWorkflowStaticData('global');
if(!s.backupCounts)s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
const out=[];
for(const item of $input.all()){
  s.backupCounts.processed++;
  const st=item.json.github_status;
  if(st==='new')s.backupCounts.new++;
  else if(st==='different')s.backupCounts.updated++;
  else s.backupCounts.unchanged++;
  out.push({json:{github_status:st||'same',tallied:true}});
}
return out;

const s=$getWorkflowStaticData('global');
if(!s.backupCounts)s.backupCounts={processed:0,new:0,updated:0,unchanged:0,failed:0,deleted:0};
const items=$input.all();
s.backupCounts.deleted+=items.length;
return items.map(i=>({json:{...i.json,tallied:true}}));

